        adj[i][i] = 0

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if adj[i][k] + adj[k][j] < adj[i][j]:
                    adj[i][j] = adj[i][k] + adj[k][j]

    return gaussian_elimination(adj)

def permutation_circuit_threshold(graph):
    n = len(graph)
